Here is the commit message:
mtd: spi-nor: debugfs: fix out-of-bounds read in
 spi_nor_params_show()

Sashiko noticed an out-of-bounds read [1].

In spi_nor_params_show(), the snor_f_names array is passed to
spi_nor_print_flags() using sizeof(snor_f_names).

Since snor_f_names is an array of pointers, sizeof() returns the total
number of bytes occupied by the pointers
	(element_count * sizeof(void *))
rather than the element count itself. On 64-bit systems, this makes the
passed length 8x larger than intended.

Inside spi_nor_print_flags(), the 'names_len' argument is used to
bounds-check the 'names' array access. An out-of-bounds read occurs
if a flag bit is set that exceeds the array's actual element count
but is within the inflated byte-size count.

Correct this by using ARRAY_SIZE() to pass the actual number of
string pointers in the array.

Cc: stable@vger.kernel.org
Fixes: 0257be79fc4a ("mtd: spi-nor: expose internal parameters via debugfs")
Closes: https://sashiko.dev/#/patchset/20260417-die-erase-fix-v2-1-73bb7004ebad%40infineon.com [1]
Signed-off-by: Tudor Ambarus <tudor.ambarus@linaro.org>
Reviewed-by: Takahiro Kuwano <takahiro.kuwano@infineon.com>
Reviewed-by: Michael Walle <mwalle@kernel.org>
Reviewed-by: Pratyush Yadav <pratyush@kernel.org>
Signed-off-by: Miquel Raynal <miquel.raynal@bootlin.com>

Here is the root cause:
Using `sizeof(snor_f_names)` instead of `ARRAY_SIZE(snor_f_names)` to pass the element count of an array of pointers to `spi_nor_print_flags()`. Since `sizeof()` returns the total byte size of the pointer array (which is element_count * sizeof(void*)), on 64-bit systems this value is 8 times larger than the actual number of elements. This causes `spi_nor_print_flags()` to perform bounds-checking against an inflated length, leading to out-of-bounds reads when a flag bit is set beyond the true array size but within the inflated value.

Here is the patch:
 // SPDX-License-Identifier: GPL-2.0

+#include <linux/array_size.h>
 #include <linux/debugfs.h>
 #include <linux/mtd/spi-nor.h>

 static int spi_nor_params_show(struct seq_file *s, void *data)
 {
 	struct spi_nor *nor = s->private;
 	struct spi_nor_flash_parameter *params = nor->params;
 	struct spi_nor_erase_map *erase_map = &params->erase_map;
 	struct spi_nor_erase_region *region = erase_map->regions;
 	const struct flash_info *info = nor->info;
 	char buf[16], *str;
 	unsigned int i;

 	seq_printf(s, "name\t\t%s\n", info->name);
 	seq_printf(s, "id\t\t%*ph\n", SPI_NOR_MAX_ID_LEN, nor->id);
 	string_get_size(params->size, 1, STRING_UNITS_2, buf, sizeof(buf));
 	seq_printf(s, "size\t\t%s\n", buf);
 	seq_printf(s, "write size\t%u\n", params->writesize);
 	seq_printf(s, "page size\t%u\n", params->page_size);
 	seq_printf(s, "address nbytes\t%u\n", nor->addr_nbytes);

 	seq_puts(s, "flags\t\t");
-	spi_nor_print_flags(s, nor->flags, snor_f_names, sizeof(snor_f_names));
+	spi_nor_print_flags(s, nor->flags, snor_f_names,
+			    ARRAY_SIZE(snor_f_names));
 	seq_puts(s, "\n");

 	seq_puts(s, "\nopcodes\n");
 	seq_printf(s, " read\t\t0x%02x\n", nor->read_opcode);
 	seq_printf(s, "  dummy cycles\t%u\n", nor->read_dummy);
 	seq_printf(s, " erase\t\t0x%02x\n", nor->erase_opcode);
 	seq_printf(s, " program\t0x%02x\n", nor->program_opcode);

 	switch (nor->cmd_ext_type) {
 	case SPI_NOR_EXT_NONE:
 		str = "none";
 		break;
 	case SPI_NOR_EXT_REPEAT:
 		str = "repeat";
 		break;
 	case SPI_NOR_EXT_INVERT:
 		str = "invert";
 		break;
 	default:
 		str = "<unknown>";
 		break;
 	}
 	seq_printf(s, " 8D extension\t%s\n", str);

 	seq_puts(s, "\nprotocols\n");
 	seq_printf(s, " read\t\t%s\n",
 		   spi_nor_protocol_name(nor->read_proto));
 	seq_printf(s, " write\t\t%s\n",
 		   spi_nor_protocol_name(nor->write_proto));
 	seq_printf(s, " register\t%s\n",
 		   spi_nor_protocol_name(nor->reg_proto));

 	seq_puts(s, "\nerase commands\n");
 	for (i = 0; i < SNOR_ERASE_TYPE_MAX; i++) {
 		struct spi_nor_erase_type *et = &erase_map->erase_type[i];

 		if (et->size) {
 			string_get_size(et->size, 1, STRING_UNITS_2, buf,
 					sizeof(buf));
 			seq_printf(s, " %02x (%s) [%d]\n", et->opcode, buf, i);
 		}
 	}

 	if (!(nor->flags & SNOR_F_NO_OP_CHIP_ERASE)) {
 		string_get_size(params->size, 1, STRING_UNITS_2, buf, sizeof(buf));
 		seq_printf(s, " %02x (%s)\n", nor->params->die_erase_opcode, buf);
 	}

 	seq_puts(s, "\nsector map\n");
 	seq_puts(s, " region (in hex)   | erase mask | overlaid\n");
 	seq_puts(s, " ------------------+------------+----------\n");
 	for (i = 0; i < erase_map->n_regions; i++) {
 		u64 start = region[i].offset;
 		u64 end = start + region[i].size - 1;
 		u8 erase_mask = region[i].erase_mask;

 		seq_printf(s, " %08llx-%08llx |     [%c%c%c%c] | %s\n",
 			   start, end,
 			   erase_mask & BIT(0) ? '0' : ' ',
 			   erase_mask & BIT(1) ? '1' : ' ',
 			   erase_mask & BIT(2) ? '2' : ' ',
 			   erase_mask & BIT(3) ? '3' : ' ',
 			   region[i].overlaid ? "yes" : "no");
 	}

 	return 0;
 }
 DEFINE_SHOW_ATTRIBUTE(spi_nor_params);


